# // CẦN BÁC SĨ/CHUYÊN GIA DUYỆT NỘI DUNG NÀY TRƯỚC KHI DÙNG PRODUCTION.
"""Fixed safety response templates; never generated by the LLM."""

from __future__ import annotations

from typing import Literal

TemplateKind = Literal[
    "EMERGENCY_REDFLAG",
    "OUT_OF_SCOPE_ADMIN",
    "OUT_OF_SCOPE_PERSONALIZED",
    "OUT_OF_SCOPE_PRESCRIPTION",
]

TEMPLATES: dict[TemplateKind, str] = {
    "EMERGENCY_REDFLAG": (
        "Thông tin bạn mô tả có thể là dấu hiệu cần được xử trí y tế ngay. "
        "Vui lòng gọi cấp cứu hoặc đến cơ sở y tế gần nhất ngay bây giờ. "
        "Không tự xử trí tại nhà thay cho bác sĩ."
    ),
    "OUT_OF_SCOPE_ADMIN": (
        "Tôi không có thông tin hành chính của từng cơ sở y tế như giấy tờ, "
        "lịch khám hoặc chi phí. Vui lòng liên hệ trực tiếp bệnh viện, phòng "
        "khám hoặc tổng đài của cơ sở bạn cần hỏi."
    ),
    "OUT_OF_SCOPE_PERSONALIZED": (
        "Tôi không thể diễn giải kết quả cá nhân hoặc đưa ra kết luận cho "
        "trường hợp cụ thể. Vui lòng trao đổi trực tiếp với bác sĩ đang theo "
        "dõi và mang theo đầy đủ kết quả khám, xét nghiệm."
    ),
    "OUT_OF_SCOPE_PRESCRIPTION": (
        "Tôi không thể chỉ định, đổi thuốc, ngừng thuốc hoặc điều chỉnh liều "
        "điều trị cho trường hợp cá nhân. Vui lòng hỏi bác sĩ điều trị hoặc "
        "dược sĩ; không tự thay đổi thuốc."
    ),
}


def get_template(kind: TemplateKind) -> str:
    """Return a fixed response template by safety label."""
    return TEMPLATES[kind]
